// The Drive trigger emits the full Drive file resource, so each item carries
// id, name, mimeType and webViewLink. kaz_kakyo/audio-transcriber natively
// resolves a standard Drive FILE share link to the media behind it, so all we
// need to build is https://drive.google.com/file/d/<id>/view
//
// Reminder: the file must be link-visible ("Anyone with the link") or the
// Actor cannot download it — see the sharing sticky.
const MEDIA_EXT = /\.(mp3|m4a|mp4|wav|aac|ogg|oga|opus|flac|wma|aiff?|mov|m4v|webm|mkv|avi)$/i;
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  // Prefer the id field; fall back to digging it out of webViewLink.
  const fromLink = typeof j.webViewLink === 'string'
    ? (j.webViewLink.match(/\/file\/d\/([\w-]{10,})/) || [])[1]
    : undefined;
  const fileId = j.id || fromLink;
  if (!fileId) continue;
  const fileName = String(j.name || '');
  const mimeType = String(j.mimeType || '');
  // Keep audio/video only: Docs, Sheets, images and PDFs dropped in the same
  // folder would otherwise become error rows.
  const isMedia = mimeType.startsWith('audio/') || mimeType.startsWith('video/') || MEDIA_EXT.test(fileName);
  if (!isMedia) continue;
  out.push({
    json: {
      driveUrl: `https://drive.google.com/file/d/${fileId}/view`,
      fileId,
      fileName,
      mimeType,
      createdTime: j.createdTime || '',
    },
  });
}
return out;

// The Actor's dataset contains type:'transcript' rows (one per audio file)
// and type:'error' rows for files it could not or did not process
// (error rows are never billed) — a file that is not link-shared lands here.
// Keep only the transcripts.
return $input.all().filter((item) => item.json.type === 'transcript');
